class MyString {
    char* buffer;

public:
    // Rvalue reference parameter (consumes temp)
    MyString(MyString&& other) noexcept 
        : buffer(other.buffer) {
        other.buffer = nullptr;
    }

    // Move assignment operator
    MyString& operator=(MyString&& other) noexcept {
        if (this != &other) {
            delete[] buffer;
            buffer = other.buffer;
            other.buffer = nullptr;
        }
        return *this;
    }
    // Rule of Five (if Ctor/Dtor exist, define Move/Copy)
};

// std::move converts lvalue to rvalue reference
MyString s1;
MyString s2 = std::move(s1);

// Forwarding reference (Universal Reference)
template <typename T>
void wrapper(T&& arg) {
    // std::forward maintains value category (lvalue/rvalue)
    process(std::forward<T>(arg));
}
